<script setup lang="ts">import { computed } from "vue"; import type { ShadowLayer } from "@oriatheme/core"; const props = defineProps<{ layers: readonly ShadowLayer[] }>(); const shadow = computed(() => props.layers.map(layer => `${layer.inset ? 'inset ' : ''}${layer.x} ${layer.y} ${layer.blur} ${layer.spread} ${layer.color}`).join(", ") || "none");</script><template><div data-oria-editor-shadow-preview :style="{'--oria-shadow-preview': shadow}" :aria-label="`${layers.length} shadow layers`" /></template>
